import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Users, Plus, Search, Filter } from 'lucide-react';
import { motion } from 'framer-motion';
import api from '../utils/api';
import '../styles/groups.css';

export default function Groups() {
  const [groups, setGroups] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    fetchGroups();
  }, []);

  const fetchGroups = async () => {
    try {
      const response = await api.get('/groups');
      setGroups(response.data);
    } catch (error) {
      console.error('Error fetching groups:', error);
    } finally {
      setLoading(false);
    }
  };

  const filteredGroups = groups.filter(group =>
    group.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Loading groups...</p>
      </div>
    );
  }

  return (
    <div className="groups-container">
      <div className="groups-header">
        <div className="header-content">
          <h1>Groups</h1>
          <p>Manage your expense groups</p>
        </div>
        <button
          className="create-group-btn"
          onClick={() => navigate('/groups/new')}
        >
          <Plus size={20} />
          Create Group
        </button>
      </div>

      <div className="groups-controls">
        <div className="search-bar">
          <Search size={20} />
          <input
            type="text"
            placeholder="Search groups..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <button className="filter-btn">
          <Filter size={20} />
          Filters
        </button>
      </div>

      <div className="groups-grid">
        {filteredGroups.length === 0 ? (
          <div className="empty-state">
            <Users size={48} />
            <h3>No groups found</h3>
            <p>Create your first group to start tracking expenses</p>
            <button
              className="create-first-group-btn"
              onClick={() => navigate('/groups/new')}
            >
              Create Group
            </button>
          </div>
        ) : (
          filteredGroups.map((group, index) => (
            <motion.div
              key={group._id}
              className="group-card"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.1 }}
              onClick={() => navigate(`/group/${group._id}`)}
            >
              <div className="group-header">
                <div className="group-icon">
                  {group.name.charAt(0).toUpperCase()}
                </div>
                <div className="group-info">
                  <h3>{group.name}</h3>
                  <p>{group.members?.length || 0} members</p>
                </div>
              </div>
              <div className="group-stats">
                <div className="stat">
                  <span className="label">Total Expenses</span>
                  <span className="value">${group.totalExpenses || 0}</span>
                </div>
                <div className="stat">
                  <span className="label">Your Balance</span>
                  <span className={`value ${group.userBalance >= 0 ? 'positive' : 'negative'}`}>
                    ${Math.abs(group.userBalance || 0)}
                  </span>
                </div>
              </div>
            </motion.div>
          ))
        )}
      </div>
    </div>
  );
}
